style.css:
@-moz-document domain("pypi.org"), domain("policies.python.org") {
:root { color-scheme: dark !important; }

  /* ---- Base surfaces ---- */
  html, body { background-color: #14181d !important; color: #c4cdd6 !important; }
  main, .content, .horizontal-section, .horizontal-section--thin,
  .tabs-container, .vertical-tabs, .vertical-tabs__panel { background-color: transparent !important; }
  .horizontal-section--grey { background-color: #1a1f26 !important; }

  /* ---- Soften all default light borders (211,211,211 etc.) to subtle dark ---- */
  * { border-color: #262c33 !important; }

  /* ---- Header / nav (dark with a PyPI-blue accent) ---- */
  /* No sticky bar exists in warehouse's CSS; .mobile-search (#005d94) is the only
     other header surface, and it only unhides at the narrow breakpoint. */
  .site-header, .mobile-search { background-color: #0d1117 !important; }
  .site-header { border-bottom: 2px solid #2f6fb8 !important; }
  .banner { background-color: #1a1f26 !important; }
  .horizontal-menu, .horizontal-menu__item, .horizontal-menu__link { background-color: transparent !important; }
  /* Language picker strip: a #0070b2 band that reads as brand trim on PyPI's blue
     footer, but glares as a bright stripe between our dark footer and sponsors. */
  .language-switcher { background-color: #1a1f26 !important; border-top: 1px solid #262c33 !important; }

  /* ---- Header "Menu" dropdown + row action menus ----
     .dropdown__content is position:absolute, so it must stay OPAQUE. The plain
     variant is a white panel (#fff/#464646); .dropdown--on-menu paints its links
     #0073b7, and our global link blue on top of that renders blue-on-blue. */
  .dropdown__content { background-color: #1c2128 !important; border-color: #2d333b !important; }
  .dropdown__link, .dropdown button.dropdown__link,
  .dropdown--on-menu .dropdown__link, .dropdown--on-menu button.dropdown__link {
    background-color: #1c2128 !important; color: #e6edf3 !important; border-bottom-color: #2d333b !important; }
  .dropdown__link a { color: #e6edf3 !important; }
  .dropdown__link:hover, .dropdown__link:focus, .dropdown__link:active,
  .dropdown button.dropdown__link:hover, .dropdown button.dropdown__link:focus,
  .dropdown button.dropdown__link:active {
    background-color: #21262d !important; color: #e6edf3 !important; }

  /* ---- Typography ---- */
  h1, h2, h3, h4, h5, h6, .package-header__name, .sidebar-section__title { color: #e6edf3 !important; }
  p, li, dd, dt, .package-description, .sidebar-section, td, th,
  b, em, strong, small, sub, sup, abbr, label, time, figcaption,
  .package-header__date, .sidebar-section__maintainer,
  .package-snippet__meta, .package-snippet__description, .package-snippet__name, .package-snippet__version,
  .package-snippet__created,
  .horizontal-menu__link, .sponsors__name, .sponsors__service, .sponsors__cycle { color: #c4cdd6 !important; }
  a, a span { color: #5fb0e6 !important; }
  a:hover, .horizontal-menu__link:hover { color: #9bd4ff !important; }
  /* The typography rule above lists strong/abbr/small/em/b/time, which also catches the
     ones nested INSIDE a link (the GitHub-statistics rows, the FAQ's <abbr>s): those
     rendered body-grey instead of taking their link's colour. Let them follow the anchor. */
  a strong, a abbr, a small, a em, a b, a time, a li { color: inherit !important; }
  /* Badge / status-pill text. These pills keep their own semantic background, so the
     text colour has to follow the pill, not the global link blue. The three light
     pills (base .status-badge #fff, --warn/--warning #ffdf76, --neutral #ececec)
     need DARK text — a blanket #fff makes "PRE-RELEASE" white-on-pale-yellow. */
  .status-badge, .status-badge span, a.status-badge, a.status-badge span,
  .badge, .badge a, .badge span {
    color: #fff !important; text-decoration: none !important; }
  .status-badge { background-color: #1c2128 !important; }
  .status-badge--good { background-color: #148024 !important; }
  .status-badge--bad { background-color: #d52d40 !important; }
  .status-badge--warn { background-color: #ffdf76 !important; }
  /* The `a.status-badge span` selector above is (0,1,2), so a plain
     `.status-badge--warn span` (0,1,1) LOSES to it and the label on the pale-yellow
     pill renders white at ~1.6:1 (the pill's ::before icon inherits it too). The
     modifier needs to out-specify the base, hence the doubled class. */
  .status-badge--warn, .status-badge--warn span,
  a.status-badge.status-badge--warn, a.status-badge.status-badge--warn span,
  .badge--warning, .badge--warning a, .badge--warning span { color: #3d2f02 !important; }
  .badge--neutral { background-color: #2d333b !important; }
  .badge--neutral, .badge--neutral a, .badge--neutral span { color: #c4cdd6 !important; }
  /* Every badge/status pill draws a 1px border in its OWN fill colour, which the
     blanket `*` reset above flattens to chrome grey — each coloured pill ends up
     ringed in a dark rim that eats a pixel of its fill. Give each variant its
     border back; the neutral pair follows our repainted surfaces. */
  .badge { border-color: #006dad !important; }
  .badge--success { border-color: #148024 !important; }
  .badge--danger { border-color: #d52d40 !important; }
  .badge--warning { border-color: #ffdf76 !important; }
  .badge--neutral { border-color: #2d333b !important; }
  .status-badge { border-color: #2d333b !important; }
  .status-badge--good { border-color: #148024 !important; }
  .status-badge--bad { border-color: #d52d40 !important; }
  .status-badge--warn { border-color: #ffdf76 !important; }
  /* Applied search-filter chip: the divider before its remove button is a
     translucent white rule on the chip's blue fill, not page chrome. */
  .filter-badge__remove-button { border-left-color: rgba(255, 255, 255, .2) !important; }
  /* Search filter accordion labels: PyPI's #006dad is too dark on dark → theme link blue */
  .accordion__link, .accordion__link.-js-accordion-trigger, [class*="accordion"] a {
    color: #5fb0e6 !important; }
  /* Pseudo-element icon glyphs (content:"") carry no text node, so colour audits
     walk straight past them. FAQ headings ship #006dad (3.2:1); the sponsor
     "hooray" checkmarks ship #464646 (1.8:1) — both unreadable on dark. */
  .faq-group h3::before { color: #5fb0e6 !important; }
  .hooray-list li::before { color: #8b949e !important; }

  /* ---- Sidebar / tab icons: readable blue (PyPI's #006dad is too dark on dark) ---- */
  .sidebar-section .fa, .sidebar-section [class*="fa-"],
  .vertical-tabs__tab .fa, .vertical-tabs__tab [class*="fa-"] { color: #5fb0e6 !important; }
  .vertical-tabs__tab--is-active .fa, .vertical-tabs__tab--is-active [class*="fa-"] { color: #e6edf3 !important; }
  /* ...except the verification check, which keeps its green (and only it) */
  .sidebar-section .fa-circle-check, .fa-circle-check, .fa-check-circle { color: #3fb950 !important; }

  /* ---- Sponsor / ethical callouts (strip leftover blue) ---- */
  .sponsors, .sponsorship, [class*="sponsor"], .ethical-callout, .ethical-sidebar { background-color: transparent !important; }
  /* The /sponsors/ grid logos are ink-on-white artwork uploaded by each sponsor (mostly
     transparent PNGs with black lettering): on a dark tile Jane Street, Snowflake and
     ReversingLabs render black-on-black and simply vanish. No filter fixes them without
     wrecking the coloured marks, so give each logo back the light plate it was drawn
     for. The footer strip uses .sponsors__image — white-ink variants — and is untouched. */
  .sponsor-grid__sponsor-img {
    background-color: #e6edf3 !important; border-radius: 6px !important; padding: 10px !important; }
  /* The blanket [class*="sponsor"] transparent above also swallowed the sponsorship
     package card's own header band (#006dad) and its icon disc, so the card lost the
     split between header and body entirely. Give them an elevated surface back and keep
     the card's blue ring, the way the site header keeps its blue trim. */
  .sponsor-package { border-color: #2f6fb8 !important; }
  .sponsor-package__header, .sponsor-package__icon { background-color: #1c2128 !important; }
  /* EthicalAds ships its "Ad by EthicalAds" disclosure at #707070, which passed on the
     white docs page and drops to ~3:1 on ours. It is the ad-transparency label — keep it
     readable. Its own sheet is cross-origin (unreadable) and outranks a plain
     `.ethical-callout a`, so the link needs the extra specificity. */
  .ethical-callout, .ethical-callout small, .ethical-callout em,
  div.ethical-callout a[href], .ethical-sidebar div.ethical-callout a { color: #8b949e !important; }

  /* ---- Code blocks ---- */
  pre, code, tt, kbd, samp, .docutils.literal,
  .highlight, .highlight pre, .package-description pre, .package-description code,
  .package-header__pip-instructions, .package-header__pip-instructions code, .package-header__pip-instructions span {
    background-color: #1c2128 !important; color: #e6edf3 !important; border-color: #2d333b !important; }

  /* ---- Pygments dark syntax palette (scoped to code: pre / .highlight / .codehilite) ---- */
  pre .c, pre .c1, pre .cm, pre .ch, pre .cs, pre .cp, pre .gp,
  .highlight .c, .highlight .c1, .codehilite .c, .codehilite .c1 { color: #8b949e !important; }
  pre .k, pre .kn, pre .kc, pre .kd, pre .kp, pre .kr, pre .kt, pre .o, pre .ow,
  .highlight .k, .highlight .kn, .codehilite .k, .codehilite .kn { color: #ff7b72 !important; }
  pre .s, pre .s1, pre .s2, pre .sb, pre .sc, pre .sd, pre .se, pre .sh, pre .si, pre .sx, pre .sr, pre .ss, pre .dl,
  .highlight .s1, .highlight .s2, .codehilite .s1, .codehilite .s2 { color: #a5d6ff !important; }
  pre .m, pre .mi, pre .mf, pre .mh, pre .mo, pre .il, .highlight .mi, .codehilite .mi { color: #79c0ff !important; }
  pre .nn, pre .nc, pre .no, .highlight .nn, .codehilite .nn { color: #ffa657 !important; }
  pre .nf, pre .fm { color: #d2a8ff !important; }
  pre .nb, pre .bp, pre .nv, pre .vc, pre .vg, pre .vi,
  pre .na, .highlight .na, .codehilite .na { color: #79c0ff !important; }
  pre .nd, pre .ni, pre .ne, pre .nl, pre .nt { color: #7ee787 !important; }
  pre .p, pre .n, pre .nx { color: #c9d1d9 !important; }
  pre .err { color: #ffa198 !important; background: transparent !important; }

  /* ---- Tabs ----
     Warehouse gives .vertical-tabs__tab no border at all (border-width:0), so a bare
     border-left-color never paints: the active tab used to be indistinguishable from
     a hovered one. Declare the width too, and pull the padding back by 3px so the
     label doesn't shift. */
  .vertical-tabs__tab { color: #c4cdd6 !important; border-color: #2d333b !important; }
  .vertical-tabs__tab:hover { background-color: #1c2128 !important; color: #e6edf3 !important; }
  .vertical-tabs__tab--is-active, .vertical-tabs__tab--is-active:hover {
    background-color: #1c2128 !important; color: #e6edf3 !important;
    border-left: 3px solid #5fb0e6 !important; padding-left: 12px !important; }

  /* ---- Tables (incl. README HTML tables: neutralize light base + odd rows) ---- */
  table, th, td, .table { border-color: #2d333b !important; }
  table, .table { background-color: #1a1f26 !important; }
  tr { background-color: transparent !important; }
  thead, th { background-color: #1c2128 !important; }
  tr:nth-child(even) { background-color: #1c2128 !important; }

  /* ---- Forms ---- */
  input, textarea, select { background-color: #1c2128 !important; color: #e6edf3 !important; border-color: #2d333b !important; }
  /* PyPI's #757575 placeholder passed on white but only reaches 3.5:1 on our input bg */
  input::placeholder, textarea::placeholder { color: #8b949e !important; opacity: 1 !important; }
  .search-form__button, .button--search { background-color: #21262d !important; border-color: #2d333b !important; }
  /* Classifier tree connectors are ::before/::after borders, which `*` cannot reach,
     so they keep warehouse's #bbb and end up as bright as the labels. */
  .checkbox-tree li::before, .checkbox-tree li::after { border-color: #3d444d !important; }
  /* Field validation messages (login / register / forgot-password / reset). Warehouse
     colours the whole list #d52d40 and the "valid" row #148024; the global `li` rule
     flattened both to body grey, leaving only the tiny ::before glyph to tell a failure
     from a pass. Those glyphs sit at ~3.3:1 on our base, so lift them along with the
     text rather than pairing bright text with a dim icon. */
  .form-errors, .form-errors li, .form-errors li::before,
  .form-errors li a, .form-errors li a:hover { color: #ff8b96 !important; }
  .form-errors .form-error--valid, .form-errors .form-error--valid::before { color: #3fb950 !important; }
  /* Password-strength meter: the filled gauge keeps its own semantic colour, but the
     TRACK is a bare 1px #d3d3d3 ring that `*` flattens to #262c33 — invisible on the
     base, so the unfilled remainder vanishes and the bar loses its scale. */
  .password-strength { background-color: #1c2128 !important; border-color: #3d444d !important; }

  /* ---- Buttons ----
     .button is !important, so it also swallows the semantic variants' own colours
     (danger red, warning gold) and the disabled affordance. Restore them after. */
  .button { background-color: #21262d !important; color: #e6edf3 !important; border-color: #2d333b !important; }
  .button--primary { background-color: #2563a8 !important; border-color: #2f6fb8 !important; color: #fff !important; }
  /* Warehouse's tertiary is the FILLED neutral (#fff on #bbb) against a base button that
     is transparent, so the two are a pair. Our base fill collapsed them into the same
     swatch; keep tertiary one step lighter to preserve the distinction. */
  .button--tertiary { background-color: #2d333b !important; border-color: #444c56 !important; }
  .button--danger { background-color: #d52d40 !important; border-color: #d52d40 !important; color: #fff !important; }
  .button--warning { background-color: #664e04 !important; border-color: #664e04 !important; color: #fff !important; }
  .button--disabled, .button[disabled] {
    background-color: #1a1f26 !important; border-color: #262c33 !important; color: #7d8590 !important; }
  /* The base rules above are !important on a single class, so warehouse's own :hover /
     :focus declarations (same specificity, never important) can no longer land: every
     button on the site sat completely inert under the cursor. Re-declare the states. */
  .button:hover, .button:focus { border-color: #5fb0e6 !important; color: #fff !important; }
  .button--primary:hover, .button--primary:focus {
    background-color: #2f6fb8 !important; border-color: #9bd4ff !important; color: #fff !important; }
  .button--danger:hover, .button--danger:focus {
    background-color: #c6283a !important; border-color: #ff8b96 !important; color: #fff !important; }
  .button--warning:hover, .button--warning:focus {
    background-color: #523f03 !important; border-color: #d8b23a !important; color: #fff !important; }
  .button--disabled:hover, .button--disabled:focus,
  .button[disabled]:hover, .button[disabled]:focus {
    background-color: #1a1f26 !important; border-color: #262c33 !important; color: #7d8590 !important; }

  /* ---- Callouts / notifications ---- */
  .callout-block, .notification-bar, .banner, .filter-panel, .statistics-bar {
    background-color: #1a1f26 !important; color: #c4cdd6 !important; border-color: #2d333b !important; }
  /* ...but keep each callout's semantic ring (the blanket `*` border-color flattens them).
     The BASE callout is a semantic too: warehouse rings it 2px #006dad, so without this
     an info callout keeps only its left bar and loses the frame entirely. Variants must
     stay BELOW this rule — they tie it on specificity and win on source order. */
  .callout-block { border-color: #2f6fb8 !important; }
  .callout-block--danger { border-color: #d52d40 !important; }
  .callout-block--warning { border-color: #8a6a06 !important; }
  .callout-block--success { border-color: #148024 !important; }
  /* Warehouse paints the whole body of a semantic callout in its own hue
     (`--danger` #d52d40, `--warning` #664e04, `--success` #148024). Our `.callout-block`
     colour plus the global `p, li, …` rule flattened all three to body grey, so a yanked
     release's reason read exactly like a neutral note — the ring was the only signal
     left. Re-tuned for dark: the natives are 2-3:1 here. Links stay theme-blue so they
     still read as links, and `.button` keeps its own colour (it is never a p/li). */
  .callout-block--danger, .callout-block--danger p, .callout-block--danger li,
  .callout-block--danger strong, .callout-block--danger em,
  .callout-block--danger .callout-block__heading { color: #ff8b96 !important; }
  .callout-block--warning, .callout-block--warning p, .callout-block--warning li,
  .callout-block--warning strong, .callout-block--warning em,
  .callout-block--warning .callout-block__heading { color: #e3b341 !important; }
  .callout-block--success, .callout-block--success p, .callout-block--success li,
  .callout-block--success strong, .callout-block--success em,
  .callout-block--success .callout-block__heading { color: #3fb950 !important; }
  /* The warning callout's left bar keeps warehouse's #664e04 (2.1:1 here) while its ring
     is already re-tuned above — lift the bar to match instead of leaving it half-done. */
  .callout-block--warning::before, .callout-block--warning::after { background-color: #8a6a06 !important; }
  /* The neutral callout paints its left/right bars through ::before / ::after, which the
     blanket `*` border rule cannot reach and no background-color rule touches, so they
     keep warehouse's #d3d3d3 and glare as a bright grey slab against the dark card. */
  .callout-block--neutral { border-color: #3d444d !important; }
  .callout-block--neutral::before, .callout-block--neutral::after { background-color: #3d444d !important; }
  /* Flash-message bars. The base rule above is !important on a single class, so it also
     swallows warehouse's semantic variants (equal specificity, none important): an
     "Invalid token" error and a "Saved" confirmation both rendered as the same grey
     strip. Restore the site's own fills and their on-colour text. */
  .notification-bar--danger { background-color: #d52d40 !important; color: #fff !important; }
  .notification-bar--success { background-color: #148024 !important; color: #fff !important; }
  .notification-bar--warning, .notification-bar--banner {
    background-color: #ffdf76 !important; color: #3d2f02 !important; }
  .notification-bar--danger .notification-bar__message a:not(.button),
  .notification-bar--success .notification-bar__message a:not(.button) { color: #fff !important; }
  .notification-bar--warning .notification-bar__message a:not(.button),
  .notification-bar--banner .notification-bar__message a:not(.button) { color: #3d2f02 !important; }
  /* ---- Modals (delete-project / remove-role confirmations, manage pages) ----
     .modal__content is a hard #fff panel; on top of it our heading rule paints
     .modal__title #e6edf3, i.e. white on white. The node is display-gated behind
     :target, so no load-time scan of a public page can ever see it. */
  .modal__content { background-color: #1c2128 !important; }
  .modal__footer { border-top-color: #2d333b !important; }
  .modal__close, .modal__close:hover { color: #c4cdd6 !important; }
  blockquote { background-color: #1a1f26 !important; border-left-color: #2d333b !important; }
  /* Warehouse draws rules as a BACKGROUND on <hr>, not a border: a #ececec fill on
     section dividers and a linear-gradient(90deg,#d3d3d3,#fff) on README rules. So
     border-color alone leaves a bright bar, and background-color alone leaves the
     gradient — both have to go. */
  hr { background-color: #2d333b !important; background-image: none !important;
    border-color: #2d333b !important; }

  /* ---- Home "about PyPI" logotype ----
     logo-large.svg is an <img>, so its inner paths are unreachable: the "python Package
     Index" wordmark is a hard #3b3b3b that lands at ~1.6:1 on our dark section, while the
     cubes beside it are white/blue/yellow. Every filter that lifts the wordmark (invert,
     brightness) wrecks the cubes, so plate the image the way the native white page does,
     in the theme's muted grey rather than a glaring white. */
  .about-pypi__logo img, img[src*="logo-large"] {
    background-color: #c4cdd6 !important; padding: 12px !important; border-radius: 8px !important; }

  /* ---- 404 / error pages ---- */
  /* Full-viewport #006dad hero: not "light", so both scanners walk past it. */
  .viewport-section--dark { background-color: #1a1f26 !important; }
  /* The easter-egg heading keeps its yellow plate, so its text must stay dark navy */
  .viewport-section--ee .viewport-section__heading { color: #003d61 !important; }
  /* The easter-egg video sits in a `border: 9px dashed #fff` film-strip frame. The blanket
     `*` border reset flattened it to chrome grey on the navy plate, so the frame vanished. */
  .viewport-section--ee .viewport-section__video-container { border-color: #8b949e !important; }

  /* ---- Search result cards ---- */
  /* The card's package glyph is a pure-white cubes.svg painted as a background-image,
     so it glares on the dark card and no filter can reach it. Blending it against the
     card colour dims it to a muted grey (~#4d5662), matching the timeline cubes below.
     multiply erases it outright; soft-light keeps the 3D shading. */
  .package-snippet { background-color: #1a1f26 !important; border-color: #2d333b !important;
    background-blend-mode: soft-light !important; }
  .package-snippet:hover { background-color: #21262d !important; border-color: #5fb0e6 !important; }

  /* ---- Release-history cards (release timeline tab) ---- */
  .release, .release__card, .release--current {
    background-color: #1a1f26 !important; border-color: #2d333b !important; }
  .release:hover, .release__card:hover { background-color: #21262d !important; }
  .release__version, .release__version-badge, .release .release__version,
  .release time, .release__card time, .release__graphic time { color: #e6edf3 !important; }
  .release__meta, .release .release__meta { color: #c4cdd6 !important; }
  /* White "cube" SVG icons (release-timeline nodes + footer mascot) glare bright on
     dark. Drop the near-white tile bg PyPI puts behind release nodes, and dim every
     white-cube image to a muted grey, leaving the blue "this version" cube to pop. */
  img.release__node { background-color: transparent !important; }
  img[src*="white-cube"] { filter: brightness(0.42) !important; }
  /* The vertical connector between release nodes is a tiled light (#ececec) PNG
     (audit-blind — a URL, not a gradient). Repaint it as a subtle 2px dark line
     matching the theme borders so it doesn't glare on the dark timeline. */
  .release__line {
    background-image: linear-gradient(#2d333b, #2d333b) !important;
    background-size: 2px 100% !important;
    background-repeat: no-repeat !important;
    background-position: 50% 50% !important; }

  /* ---- MkDocs Material policy/docs pages (policies.python.org) ----
     PyPI's Terms/Privacy/Code-of-Conduct pages moved off pypi.org/policy/* to the
     standalone policies.python.org MkDocs Material site (hence the added domain in
     the @-moz-document above). It ships its own light "psf" / dark "slate" palettes;
     on a light-OS device the light palette wins, leaving a white page under our dark
     body. MkDocs is fully CSS-variable driven, so redefine its palette vars.
     Material puts data-md-color-scheme on <body>, NOT on <html>: under the dark
     "slate" scheme body re-declares these vars on itself, and a closer ancestor beats
     an inherited !important — so a :root-only remap is a silent no-op there (verified:
     --md-default-bg-color read back as hsla(225deg,15%,14%,1) from a deep node). It
     only ever won under the light "psf" scheme, which leaves the vars on :root.
     Declaring on body too makes both schemes resolve our palette. Warehouse pages
     don't reference these vars, so this is inert everywhere else. The PSF-blue header
     (--md-primary-*) is left untouched as brand. */
  :root, body {
    --md-default-bg-color: #14181d !important;
    --md-default-fg-color: rgba(196,205,214,.9) !important;
    --md-default-fg-color--light: rgba(196,205,214,.62) !important;
    --md-default-fg-color--lighter: rgba(196,205,214,.38) !important;
    --md-default-fg-color--lightest: rgba(255,255,255,.07) !important;
